  'tasbih.when.c5_title': `ভ্রমণ ও চলার পথে`,
  'tasbih.when.c5_desc': `ভ্রমণের সময় হাতের তাসবিহের একটি বাস্তব বিকল্প — সরাসরি আপনার ফোনে চলে।`,
  'tasbih.related.title': `সম্পর্কিত সরঞ্জাম ও ইবাদত`,
  'tasbih.related.intro': `আপনার দৈনন্দিন ইবাদতের পরিপূরক কিছু উপকারী লিংক:`,
  'tasbih.related.prayer_title': `নামাজের সময়সূচি`,
